import {STATIONS,SPECS,step,newRun,stoppingDistance,assistBrake,notchDeltaForKey} from './physics.js';
import {RouteProfile} from './route-profile.js';
import {RailWorld} from './scene.js';
import {SoundEngine} from './assets/audio/sound-engine.js';
const $=id=>document.getElementById(id), sound=new SoundEngine();
let profile,world,run=newRun(),mode='menu',paused=false,assist=false,rate=1,panorama=false,toastUntil=6,wall=0,rendered=false,bootError='';
const settings={volume:.65};
try{settings.volume=Number(localStorage.getItem('tohoku-volume')??.65);}catch{}
sound.setVolume(settings.volume);
function toast(t,seconds=5){$('toast').textContent=t;toastUntil=wall+seconds;}
const strip=['EB','B7','B6','B5','B4','B3','B2','B1','N','P1','P2','P3','P4','P5'];
$('notchStrip').innerHTML=strip.map((n,i)=>`<span data-notch="${i-8}">${n}</span>`).join('');
$('journeyTrack').innerHTML=STATIONS.map(x=>`<span>${x.name}</span>`).join('');
for(let n=0;n<=120;n+=10){const a=(-130+n/120*260)*Math.PI/180,x=100+Math.sin(a)*72,y=85-Math.cos(a)*72,tx=100+Math.sin(a)*57,ty=85-Math.cos(a)*57;const ns='http://www.w3.org/2000/svg',line=document.createElementNS(ns,'line');line.setAttribute('x1',x);line.setAttribute('y1',y);line.setAttribute('x2',100+Math.sin(a)*65);line.setAttribute('y2',85-Math.cos(a)*65);line.setAttribute('stroke','#424d42');$('ticks').append(line);if(n%20===0){const t=document.createElementNS(ns,'text');t.setAttribute('x',tx);t.setAttribute('y',ty+3);t.setAttribute('fill','#343d31');t.setAttribute('text-anchor','middle');t.setAttribute('font-size','8');t.textContent=n;$('ticks').append(t);}}
const geometryPromise=fetch('./assets/route-geometry.json').then(r=>{if(!r.ok)throw Error('線路座標を取得できません');return r.json();});
function info(html){$('infoContent').innerHTML=html;$('info').showModal();}
$('closeInfo').onclick=()=>$('info').close();
const help=`<p class="eyebrow">DRIVING GUIDE</p><h2>最初の出発、ここから。</h2><p><kbd>S / ↓</kbd>でP5方向へ、<kbd>W / ↑</kbd>でEB方向へ1段ずつ動かします。<kbd>X</kbd>は惰行、<kbd>Space</kbd>は非常ブレーキです。画面のボタンでも操作できます。</p><p>まずSを5回押してP5で出発。駅の手前ではXで惰行にしてから、WでB1〜B7に入れます。停止位置の±12mで停車したら、Oでドアを開けて5秒待ち、もう一度Oで閉めて出発しましょう。</p><p>「停車アシスト」をONにすると、駅の手前で減速と停車を補助します。加速操作は自分で行います。「速度 ×1」は×3・×10に切替可能。まず操作を試すときに使えます。</p><p>Escで一時停止。通過や行き過ぎは「前駅から再開」でやり直せます。</p>`;
$('helpButton').onclick=()=>info(help);
$('routeButton').onclick=()=>info(`<p class="eyebrow">ROUTE & ROLLING STOCK</p><h2>黒磯 → 新白河</h2><table>${STATIONS.map((x,i)=>`<tr><td>${x.name}</td><td>${i?((x.s-STATIONS[i-1].s)/1000).toFixed(1)+' km':'出発駅'}</td><td>${(x.s/1000).toFixed(1)} km</td></tr>`).join('')}</table><p>701系1500番台・2両編成。起動加速度2.1 km/h/s、常用・非常減速度3.6 km/h/s、最高速度110 km/h。</p><p>線路の平面形状はOpenStreetMap座標に基づく近似。営業キロに駅間ごと校正。勾配と常設速度制限は提供BVEデータを参照。E531系用の曲線＋10km/hを外し、701系の上限110km/hを適用。駅位置はRailLab距離へ校正。カント・駅構内配線・実際の信号・周囲の建物は簡略表現です。</p><p>黒磯での701系運転を体験する試作シナリオです。現在の営業運転の再現ではありません。</p><p><a target="_blank" href="https://raillab.jp/transport/39">駅間距離：RailLab</a> · <a target="_blank" href="https://ja.wikipedia.org/wiki/JR東日本701系電車">車両性能：Wikipedia</a> · <a target="_blank" href="https://www.openstreetmap.org/copyright">線路：OSM / ODbL</a></p>`);
$('settingsButton').onclick=()=>{info(`<p class="eyebrow">SOUND SETTINGS</p><h2>運転席の音。</h2><p>RTM 701soundpackの走行音・ドア音を使用。元スクリプトの速度別ピッチ・音量を区分線形補間して再生します。</p><label>音量 <span id="volValue">${Math.round(settings.volume*100)}</span>%<input id="volume" type="range" min="0" max="100" value="${settings.volume*100}"></label><p>動画との聴感比較は未実施。現在はRTM設定を基準にしています。</p>`);$('volume').oninput=e=>{settings.volume=e.target.value/100;sound.setVolume(settings.volume);$('volValue').textContent=e.target.value;try{localStorage.setItem('tohoku-volume',settings.volume);}catch{}};};
async function ensureWorld(){if(world)return;const [g,p]=await Promise.all([geometryPromise,fetch('./assets/bve-profile.json').then(r=>{if(!r.ok)throw Error('BVE路線データを取得できません');return r.json();})]);profile=new RouteProfile(p);world=new RailWorld($('world'),g,STATIONS,profile);}
async function start(){
 $('start').disabled=true;$('start').querySelector('span').textContent='運転席を準備中…';
 // Start AudioContext synchronously within the button's user gesture.
 sound.init().then(()=>{if(mode==='menu'||paused)sound.setPaused(true);}).catch(e=>toast('走行音の読み込み失敗：'+e.message,12));
 try{await ensureWorld();run=newRun();mode='drive';paused=false;sound.setPaused(false);$('menu').hidden=true;$('drive').hidden=false;$('continue').hidden=false;toast('黒磯を出発。S／↓で力行、W／↑で制動。初めてなら停車アシストも使えます。',9);}catch(e){bootError=e.message;info(`<h2>運転画面を起動できませんでした</h2><p>${e.message}</p><p>WebGL対応のブラウザーで開いてください。</p>`);}finally{$('start').disabled=false;$('start').querySelector('span').textContent='最初から運転する';}
}
$('start').onclick=start;
function toMenu(){mode='menu';paused=true;sound.setPaused(true);$('drive').hidden=true;$('menu').hidden=false;if($('pauseDialog').open)$('pauseDialog').close();}
$('menuButton').onclick=toMenu;$('pauseMenu').onclick=toMenu;
$('continue').onclick=()=>{mode='drive';$('menu').hidden=true;$('drive').hidden=false;paused=false;sound.resume();};
function pause(){if(mode!=='drive'||run.finished)return;paused=true;sound.setPaused(true);$('pauseDialog').showModal();}
function resume(){paused=false;$('pauseDialog').close();sound.resume();}
$('pauseButton').onclick=pause;$('resume').onclick=resume;
$('pauseDialog').addEventListener('cancel',e=>{e.preventDefault();resume();});
function setNotch(n){if(mode!=='drive'||paused||run.finished)return;if(run.doors&&n>0){toast('ドアが開いています。Oで閉めてください。');return;}run.notch=Math.max(-8,Math.min(5,n));}
function doors(){if(mode!=='drive'||paused||run.finished)return;if(run.v>.12){toast('ドアは停車中に操作してください。');return;}if(!run.stopReady){toast('停車位置の±12mに停車してください。');return;}if(!run.doors){run.doors=true;run.notch=-4;run.dwell=0;sound.playEffect('open');toast('ドアを開きました。5秒停車したらOで閉めてください。');}else{if(run.dwell<5){toast(`乗降中。あと${Math.ceil(5-run.dwell)}秒待ってください。`,2);return;}run.doors=false;sound.playEffect('close');run.served++;const error=run.s-STATIONS[run.next].s;run.errors.push(error);run.next++;run.assistBraking=false;run.stopReady=false;run.dwell=0;run.notch=0;if(run.next===STATIONS.length){run.finished=true;showResult();}else toast(`戸閉よし。次は${STATIONS[run.next].name}。S／↓で出発。`);}}
function showResult(){paused=true;sound.setPaused(true);const avg=run.errors.length?run.errors.reduce((a,b)=>a+Math.abs(b),0)/run.errors.length:0;info(`<p class="eyebrow">JOURNEY COMPLETE</p><h2>新白河に到着。</h2><p>乗務おつかれさま！</p><table><tr><td>運転距離</td><td>22.1 km</td></tr><tr><td>停車できた駅</td><td>${run.served} / 5</td></tr><tr><td>通過した駅</td><td>${run.missed}</td></tr><tr><td>平均停止位置誤差</td><td>${avg.toFixed(1)} m</td></tr><tr><td>速度制限を超過した時間</td><td>${Math.round(run.overspeedSeconds??0)}秒</td></tr><tr><td>運転時間</td><td>${Math.floor(run.elapsed/60)}分${Math.floor(run.elapsed%60)}秒</td></tr></table><button id="resultMenu" class="primary">メニューへ</button>`);$('resultMenu').onclick=()=>{$('info').close();toMenu();};}
$('doors').onclick=doors;$('powerUp').onclick=()=>setNotch(run.notch+1);$('brakeDown').onclick=()=>setNotch(run.notch-1);$('neutral').onclick=()=>setNotch(0);$('emergency').onclick=()=>setNotch(-8);
$('notchStrip').onclick=e=>{if(e.target.dataset.notch)setNotch(Number(e.target.dataset.notch));};
$('assist').onclick=()=>{assist=!assist;run.assistBraking=false;$('assist').textContent='停車アシスト '+(assist?'ON':'OFF');toast(assist?'駅手前の減速・停止を補助します。':'停車アシストを解除しました。');};
$('rate').onclick=()=>{rate=rate===1?3:rate===3?10:1;$('rate').textContent='速度 ×'+rate;$('simRate').textContent=rate===1?'REAL TIME':`TIME ×${rate}`;};
$('viewButton').onclick=()=>{panorama=!panorama;$('drive').classList.toggle('panorama',panorama);$('viewButton').textContent=panorama?'運転台を表示':'前面展望';};
$('retry').onclick=()=>{if(run.finished)return;run.assistBraking=false;run.s=STATIONS[Math.max(0,run.next-1)].s;run.v=0;run.notch=0;run.doors=false;run.stopReady=false;run.dwell=0;toast('前駅から再開します。');};
document.addEventListener('keydown',e=>{if(e.target.matches('input'))return;if(mode!=='drive'||$('info').open)return;if(e.code==='Escape'){e.preventDefault();if(!paused)pause();return;}if(paused||e.repeat)return;switch(e.code){case'KeyW':case'ArrowUp':case'KeyS':case'ArrowDown':e.preventDefault();setNotch(run.notch+notchDeltaForKey(e.code));break;case'KeyX':setNotch(0);break;case'Space':e.preventDefault();setNotch(-8);break;case'KeyO':doors();break;}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='drive'&&!paused)pause();});
function advance(dt){if(run.finished)return;const next=STATIONS[run.next],d=next.s-run.s;if(run.doors)run.dwell+=dt;
 if(assist&&!run.doors&&!run.stopReady)assistBrake(run,d,profile.gradeAt(run.s));
 step(run,dt,profile.gradeAt(run.s));
 if(run.v*3.6>profile.limitAt(run.s)+1)run.overspeedSeconds=(run.overspeedSeconds??0)+dt;
 if(Math.abs(run.s-next.s)<=12&&run.v<.12&&!run.stopReady){run.stopReady=true;toast(`${next.name} 停車。Oでドアを開けてください。`);}
 if(run.stopReady&&Math.abs(run.s-next.s)>12&&!run.doors){run.stopReady=false;}
 if(run.s>next.s+35){if(run.next===5){run.v=0;run.notch=-8;paused=true;sound.setPaused(true);info('<h2>新白河の停止位置を過ぎました</h2><p>手前からもう一度チャレンジできます。</p><button id="endRetry" class="primary">1km手前から再開</button>');$('endRetry').onclick=()=>{$('info').close();run.s=21100;run.v=50/3.6;run.notch=0;run.stopReady=false;paused=false;sound.resume();};}else{toast(`${next.name}を通過しました。次は${STATIONS[run.next+1].name}です。`,8);run.missed++;run.next++;run.stopReady=false;}}
}
function hud(){const kmh=run.v*3.6,next=STATIONS[Math.min(5,run.next)],d=next.s-run.s;$('speed').textContent=Math.round(kmh);$('needle').style.transform=`rotate(${-130+kmh/120*260}deg)`;$('distance').innerHTML=(run.s/1000).toFixed(3)+' <small>km</small>';$('notch').textContent=strip[run.notch+8];$('lever').style.left=((run.notch+8)/13*100)+'%';$('notchStrip').querySelectorAll('span').forEach(el=>el.classList.toggle('selected',Number(el.dataset.notch)===run.notch));$('nextName').textContent=next.name;$('remaining').textContent=run.finished?'終点に到着':`停車まで ${d>=0?Math.round(d).toLocaleString():Math.abs(Math.round(d))+'m 行き過ぎ'}${d>=0?' m':''}`;$('served').textContent=run.served+' / 5';const sec=8*3600+Math.floor(run.elapsed);$('clock').textContent=[Math.floor(sec/3600)%24,Math.floor(sec/60)%60,sec%60].map(x=>String(x).padStart(2,'0')).join(':');$('doorLamp').classList.toggle('lit',!run.doors);$('doorLabel').textContent=run.doors?'戸開':'戸閉';$('brakeLamp').classList.toggle('lit',run.notch<0);$('audioStatus').textContent=sound.error?'音源エラー：'+sound.error:sound.ready?'RTM SOUND · '+(sound.activeTracks?.length??0)+' LAYERS':'走行音を読み込んでいます…';$('trainDot').style.left=Math.min(100,run.s/22100*100)+'%';$('journeyTrack').querySelectorAll('span').forEach((el,i)=>el.classList.toggle('done',i<run.next));
 let guidance=run.finished?'新白河に到着しました':run.doors?`乗降中 ${Math.min(5,Math.floor(run.dwell))} / 5秒 · Oで戸閉`:run.stopReady?'停車位置よし · Oでドアを開ける':d<stoppingDistance(kmh,4,profile.gradeAt(run.s))+90&&kmh>15?'まもなく停車駅 · ブレーキを調整':run.notch>0?'力行中 · Xで惰行へ':run.notch<0?'制動中 · 停止位置を確認':kmh<1?'S／↓で力行して出発しましょう':'惰行中 · 速度と距離を確認';$('guideText').textContent=guidance;const curvature=world?.curvature(run.s)??0;$('curveInfo').textContent=`OSM線形 / BVE勾配 · ${Math.abs(curvature)<.00008?'直線区間':'曲線半径 約'+Math.round(1/Math.abs(curvature))+'m'} · B4停止目安 ${Math.round(stoppingDistance(kmh,4,profile.gradeAt(run.s)))}m`;const limit=profile.limitAt(run.s),grade=profile.gradeAt(run.s),upcoming=profile.nextLimit(run.s),over=kmh>limit+1;$('limitValue').textContent=limit;$('gradient').innerHTML=(grade>0?'上り ':grade<0?'下り ':'平坦 ')+Math.abs(grade).toFixed(1)+' <small>‰</small>';$('speedWarning').textContent=(over?'速度超過　':'制限　')+limit+' km/h';$('speedWarning').classList.toggle('over',over);$('speed').classList.toggle('over',over);$('upcomingLimit').textContent=upcoming?`${Math.round(upcoming.s-run.s).toLocaleString()}m先　${upcoming.kmh} km/h`:'この先、制限変更なし';$('brakeNeedle').style.transform=`rotate(${-130+(run.notch<0?Math.min(7,-run.notch)/7*350:0)/800*260}deg)`;$('tractionLever').style.transform=`rotateX(${Math.max(0,run.notch)*-5}deg)`;$('brakeHandle').style.transform=`rotate(${Math.max(0,-run.notch)*-6}deg)`;$('toast').style.opacity=wall<toastUntil?1:0;
}
let last=performance.now();function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;wall+=dt;if(mode==='drive'&&world){if(!paused){let sim=dt*rate;while(sim>0){const chunk=Math.min(.02,sim);advance(chunk);sim-=chunk;if(paused)break;}sound.update(run.v*3.6,run.doors?0:run.notch,dt);}hud();world.render(run.s,run.v,wall,panorama);rendered=true;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
// Read-only diagnostics for reproducible local verification; no gameplay shortcuts.
window.railDiagnostics=()=>({run:{...run},mode,paused,assist,rate,rendered,audioReady:sound.ready,audioError:sound.error,activeTracks:sound.activeTracks,bootError});
